local function beast(ctx,e) for _,tag in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags) do if tag=="beast" or tag=="all" then return true end end return false end
return { api_version=1, id="DS1_070", rarity = "free", name="Houndmaster", text="<b>Battlecry:</b> Give a friendly Beast +2/+2 and <b>Taunt</b>.", set="LEGACY", type="minion", class="hunter", cost=4, attack=4, health=3, keywords={"battlecry"}, target_mode="required_if_available", targets=function(ctx,self) local r={}; for _,e in ipairs(ctx:friendly_minions(self)) do if e~=self and beast(ctx,e) then r[#r+1]=e end end return r end, on_battlecry=function(ctx,self,target) if target then ctx:buff(target,2,2); ctx:grant_keyword(target,"taunt") end end }
